(()=>{'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d',{alpha:false}),menu=document.querySelector('#menu'),hud=document.querySelector('#hud'),mobile=document.querySelector('#mobile-controls');
const $=s=>document.querySelector(s),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),TAU=Math.PI*2;
let W=480,H=270,dpr=1,last=0,active=false,paused=false,menuMode=true,elapsed=0,matchTime=300,fireHeld=false,fireCooldown=0,shotKick=0,damageFlash=0,hitTime=0,toastUntil=0,feedEntries=[];
let mode='tdm',difficulty='medium',arena='estancia',scoreBlue=0,scoreRed=0,aliveCount=6;
const player={x:4.5,y:4.5,a:0,hp:100,ammo:30,reserve:120,speed:0,vz:0,z:0,slide:0,stamina:100,kills:0,deaths:0};
const bots=[];const keys=Object.create(null);let aimTouch=false,stick={x:0,y:0,id:null,origin:null},look={id:null,x:0},settingsOpen=false;
const mapA=[
'11111111111111111111','10000000000000000001','10111001011101110001','10000001000000000001','10001100000100011001','10001101000100001001','10000001000000001001','10110000011100001001','10000000000000000001','10001011100011100001','10001000000000100001','10000000011000000001','10111000011000011101','10000000000000000001','10000111000111000001','10000000000000000001','10111000111000111001','10000000000000000001','10000000000000000001','11111111111111111111'];
const mapB=[
'11111111111111111111','10000000000000000001','10100011100011100001','10000000000000000001','10011000000000011001','10011001110011001001','10000001000100000001','10110001000100001101','10000000000000000001','10001111000111100001','10000000000000000001','10011000000000110001','10001001111001000001','10000000000000000001','10111000011000011101','10000000000000000001','10001110000001110001','10000000000000000001','10000000000000000001','11111111111111111111'];
let grid=mapA.map(r=>r.split('').map(Number));
function resize(){const cw=innerWidth,ch=innerHeight;const scale=Math.min(.62,640/cw);W=Math.max(320,Math.floor(cw*scale));H=Math.max(180,Math.floor(ch*scale));canvas.width=W;canvas.height=H;}
window.addEventListener('resize',resize,{passive:true});resize();
function cell(x,y){const ix=Math.floor(x),iy=Math.floor(y);return !grid[iy]||grid[iy][ix]!==0}
function wallColor(mx,my,side,dist){let c;if(arena==='pampa'){c=['#9d573e','#c9774d','#7e4838','#d08a54'][(mx*3+my*7)%4]}else{c=['#886642','#b28a58','#75563b','#c19a62'][(mx*5+my*3)%4]}if(side)c=shade(c,.74);const light=clamp(1-dist/11,.18,1);return shade(c,light)}
function shade(hex,k){const n=parseInt(hex.slice(1),16),r=clamp((n>>16)*k,0,255)|0,g=clamp(((n>>8)&255)*k,0,255)|0,b=clamp((n&255)*k,0,255)|0;return `rgb(${r},${g},${b})`}
function cast(ox,oy,angle,max=18){const dx=Math.cos(angle),dy=Math.sin(angle);let mx=Math.floor(ox),my=Math.floor(oy),ddx=Math.abs(1/(dx||1e-8)),ddy=Math.abs(1/(dy||1e-8)),sx=dx<0?-1:1,sy=dy<0?-1:1,sdx=(dx<0?ox-mx:mx+1-ox)*ddx,sdy=(dy<0?oy-my:my+1-oy)*ddy,side=0;for(let i=0;i<36;i++){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}if(!grid[my]||grid[my][mx]){const dist=side?(my-oy+(1-sy)/2)/dy:(mx-ox+(1-sx)/2)/dx;return {dist:Math.max(.01,Math.min(max,dist)),mx,my,side,wall:1}}}return {dist:max,mx:0,my:0,side:0,wall:0}}
function drawWorld(){
 const sky=ctx.createLinearGradient(0,0,0,H*.52);sky.addColorStop(0,arena==='pampa'?'#6da4b1':'#6db7b2');sky.addColorStop(.83,'#b3d39b');sky.addColorStop(1,'#e1d89c');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H*.56);
 // flat, low-cost sun and distant pampas silhouettes
 ctx.fillStyle='#ffe4a0';ctx.beginPath();ctx.arc(W*.77,H*.19,H*.045,0,TAU);ctx.fill();ctx.fillStyle=arena==='pampa'?'#b77754':'#77966e';ctx.beginPath();ctx.moveTo(0,H*.5);for(let x=0;x<=W;x+=25)ctx.lineTo(x,H*(.43+.03*Math.sin(x*.018)+.012*Math.sin(x*.051)));ctx.lineTo(W,H*.57);ctx.lineTo(0,H*.57);ctx.fill();
 const horizon=H*.49+(player.z?player.z*20:0),fov=1.12,depths=new Float32Array(W);
 const floor=ctx.createLinearGradient(0,horizon,0,H);floor.addColorStop(0,arena==='pampa'?'#88744d':'#7c8152');floor.addColorStop(1,arena==='pampa'?'#544d32':'#4e5e3d');ctx.fillStyle=floor;ctx.fillRect(0,horizon,W,H-horizon);
 // ground seams converge toward horizon, avoid expensive geometry/post processing
 ctx.strokeStyle='#d9cc8650';ctx.lineWidth=1;for(let i=1;i<8;i++){const y=horizon+(H-horizon)*i*i/64;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}for(let x=-5;x<12;x++){ctx.beginPath();ctx.moveTo(W/2+(x-5)*2,horizon);ctx.lineTo(W/2+(x-5)*100,H);ctx.stroke()}
 for(let x=0;x<W;x+=2){const ray=player.a+Math.atan((x/W-.5)*fov),r=cast(player.x,player.y,ray),correct=r.dist*Math.cos(ray-player.a);depths[x]=depths[x+1]=correct;const wallH=Math.min(H*1.65,H/(correct*.72)),top=horizon-wallH*.52,shadeCol=wallColor(r.mx,r.my,r.side,correct);ctx.fillStyle=shadeCol;ctx.fillRect(x,top,2,wallH);if((r.mx+r.my)%4===0){ctx.fillStyle='#e3ca8a25';ctx.fillRect(x,top+wallH*.22,2,1)}}
 drawDecor(horizon);drawBots(horizon,depths,fov);drawGun();if(damageFlash>0){ctx.fillStyle=`rgba(212,39,29,${damageFlash*.4})`;ctx.fillRect(0,0,W,H)}
}
function drawDecor(h){ // sparse fence posts and shed silhouettes at horizon
 ctx.fillStyle=arena==='pampa'?'#644337':'#4f4730';for(let i=0;i<6;i++){const dx=((i*137+50+elapsed*2)%W),y=h-4+Math.sin(i*8)*3;ctx.fillRect(dx,y,2,8);ctx.fillRect(dx-3,y+2,8,1)}
}
function drawBots(h,depths,fov){const list=bots.filter(b=>b.hp>0).map(b=>{let dx=b.x-player.x,dy=b.y-player.y,dist=Math.hypot(dx,dy),ang=Math.atan2(dy,dx)-player.a;while(ang>Math.PI)ang-=TAU;while(ang<-Math.PI)ang+=TAU;return {b,dist,ang}}).filter(o=>Math.abs(o.ang)<fov*.72&&o.dist>.2).sort((a,b)=>b.dist-a.dist);
 for(const o of list){const {b,dist,ang}=o,sx=W/2+Math.tan(ang)/(Math.tan(fov/2))*W/2,size=Math.min(H*.74,H/(dist*.9)),sy=h-size*.5;if(sx<0||sx>=W)continue;const ix=Math.floor(sx);if(dist>(depths[ix]||99)+.25)continue;const w=size*.33,head=size*.17,x=sx-w/2;ctx.save();ctx.translate(sx,sy);
 // big readable low-poly gaucho operator silhouette
 ctx.fillStyle=b.team==='blue'?'#278b7d':'#bd543b';ctx.beginPath();ctx.ellipse(0,size*.05,w*.62,size*.24,0,0,TAU);ctx.fill();ctx.fillStyle='#2e2920';ctx.fillRect(-w*.54,size*.18,w*.34,size*.24);ctx.fillRect(w*.2,size*.18,w*.34,size*.24);
 ctx.fillStyle=b.team==='blue'?'#e4be8b':'#dbbd8c';ctx.beginPath();ctx.ellipse(0,-size*.22,w*.39,head*.57,0,0,TAU);ctx.fill();ctx.fillStyle='#453527';ctx.beginPath();ctx.ellipse(0,-size*.33,w*.57,head*.24,0,Math.PI,TAU);ctx.fillRect(-w*.48,-size*.34,w*.96,head*.13);ctx.fillStyle='#211c16';ctx.fillRect(-w*.2,-size*.2,2,2);ctx.fillRect(w*.13,-size*.2,2,2);ctx.fillStyle='#272722';ctx.fillRect(w*.3,-size*.04,w*.78,Math.max(3,size*.055));ctx.fillStyle='#d6f46b';ctx.fillRect(-w*.29,size*.32,w*.58,Math.max(2,size*.035));
 if(b.hp<75){ctx.fillStyle='#171b14';ctx.fillRect(-w*.55,-size*.54,w*1.1,3);ctx.fillStyle='#f0784e';ctx.fillRect(-w*.55,-size*.54,w*1.1*b.hp/100,3)}ctx.restore();}
}
function drawGun(){const kick=shotKick*H*.08,baseX=W*.72,baseY=H*1.02+kick;ctx.save();ctx.translate(baseX,baseY);ctx.fillStyle='#19201c';ctx.beginPath();ctx.moveTo(-W*.07,0);ctx.lineTo(-W*.04,-H*.19);ctx.lineTo(W*.13,-H*.22);ctx.lineTo(W*.21,0);ctx.fill();ctx.fillStyle='#46504a';ctx.fillRect(-W*.015,-H*.21,W*.18,H*.12);ctx.fillStyle='#242b27';ctx.fillRect(W*.02,-H*.19,W*.22,H*.08);ctx.fillStyle='#111611';ctx.fillRect(W*.03,-H*.13,W*.08,H*.2);ctx.fillStyle='#917044';ctx.fillRect(W*.05,-H*.15,W*.09,H*.022);if(shotKick>.25){ctx.fillStyle='#ffe18a';ctx.beginPath();ctx.moveTo(W*.25,-H*.18);ctx.lineTo(W*.31,-H*.28);ctx.lineTo(W*.29,-H*.16);ctx.lineTo(W*.35,-H*.23);ctx.lineTo(W*.28,-H*.1);ctx.fill()}ctx.restore();}

