ctx.fill()}ctx.restore();}
function startGame(){mode=$('#mode').value;difficulty=$('#difficulty').value;arena=$('#arena').value;grid=(arena==='pampa'?mapB:mapA).map(r=>r.split('').map(Number));scoreBlue=scoreRed=0;elapsed=0;matchTime=mode==='br'?180:300;player.x=4.5;player.y=4.5;player.a=.25;player.hp=100;player.ammo=30;player.reserve=120;player.kills=0;player.deaths=0;player.speed=0;player.slide=0;player.stamina=100;bots.length=0;for(let i=0;i<5;i++)spawnBot(i);active=true;paused=false;menuMode=false;menu.classList.add('hidden');hud.style.display='block';mobile.style.display=innerWidth<850||('ontouchstart'in window)?'block':'none';$('#pause').classList.remove('visible');$('#mode-label').textContent=mode==='tdm'?'COMBATE EM EQUIPE':mode==='ffa'?'CADA UM POR SI':'ÚLTIMO VIVENTE';updateHud();say(mode==='br'?'SOBREVIVE, VIVENTE!':'BORA PRA PELEIA!');}
function spawnBot(i){const spots=[[14.5,4.5],[16.4,8.5],[12.5,13.5],[7.5,15.2],[15.8,16],[9.2,8.5],[5.3,12.5]];let p=spots[i%spots.length],x=p[0],y=p[1];if(cell(x,y)){x=14.5;y=14.5}bots.push({x,y,hp:100,team:mode==='tdm'&&i<2?'blue':'red',speed:rand(.8,1.15),fire:rand(.4,1.5),think:rand(0,1),wander:rand(0,TAU),alive:true,name:['Chico Pólvora','Dona Braba','Tchê Sniper','Baita Bagual','Zé do Galpão'][i%5]});}
function updateHud(){ $('#score').textContent=`${scoreBlue} — ${scoreRed}`;$('#hp').textContent=Math.max(0,Math.ceil(player.hp));$('#hpbar').style.width=`${clamp(player.hp,0,100)}%`;$('#mag').textContent=player.ammo;$('#reserve').textContent=player.reserve;$('#timer').textContent=`${String(Math.floor(matchTime/60)).padStart(2,'0')}:${String(Math.max(0,Math.floor(matchTime%60))).padStart(2,'0')}`;$('#alive').textContent=mode==='br'?`☻ ${Math.max(1,aliveCount)} NA PELEIA`:`☻ ${bots.filter(b=>b.hp>0).length+1} NA PELEIA`;}
function say(text){const t=$('#toast');t.textContent=text;t.style.opacity=1;toastUntil=performance.now()+1550;}
function addFeed(text){const el=document.createElement('div');el.textContent=text;$('#feed').prepend(el);setTimeout(()=>el.remove(),4200)}
function reload(){if(player.ammo>=30||player.reserve<=0)return;say('RECARREGANDO…');setTimeout(()=>{if(active){const n=Math.min(30-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;updateHud()}},650)}
function shoot(){if(!active||paused||fireCooldown>0)return;if(player.ammo<=0){fireCooldown=.38;reload();return}player.ammo--;fireCooldown=.13;shotKick=1;updateHud();let target=null,best=.095;
 for(const b of bots){if(b.hp<=0||(mode==='tdm'&&b.team==='blue'))continue;const dx=b.x-player.x,dy=b.y-player.y,d=Math.hypot(dx,dy);let da=Math.atan2(dy,dx)-player.a;while(da>Math.PI)da-=TAU;while(da<-Math.PI)da+=TAU;if(Math.abs(da)<best&&d<cast(player.x,player.y,player.a).dist+.2){best=Math.abs(da);target=b}}
 if(target){target.hp-=difficulty==='insane'?60:45;hitTime=.12;$('#hitmarker').classList.add('show');setTimeout(()=>$('#hitmarker').classList.remove('show'),100);if(target.hp<=0){scoreBlue++;player.kills++;addFeed(`${target.name}  ✕  VOCÊ  ·  baita tiro!`);if(mode==='tdm'&&target.team==='blue'){scoreBlue-=2;scoreRed++}setTimeout(()=>{if(active)respawnBot(target)},1200)}else addFeed('ACERTOU · tchê, pegou!');}else if(Math.random()<.25)addFeed('PÁ!');}
function respawnBot(b){if(mode==='br'){aliveCount--;if(aliveCount<=1){paused=true;$('#pause-title').textContent='SOBROU SÓ TU!';$('#pause-copy').textContent='O último vivente da estância. Bah, que peleia!';$('#pause').classList.add('visible')}return}const spots=[[14.5,4.5],[16.4,8.5],[12.5,13.5],[7.5,15.2],[15.8,16],[9.2,8.5]];const p=spots[Math.floor(Math.random()*spots.length)];b.x=p[0];b.y=p[1];b.hp=100;b.fire=rand(.6,1.8)}
function botUpdate(dt){for(const b of bots){if(b.hp<=0)continue;const dx=player.x-b.x,dy=player.y-b.y,d=Math.hypot(dx,dy);b.think-=dt;if(d<9){const ray=cast(b.x,b.y,Math.atan2(dy,dx));if(ray.dist>d-.2){if(d>3){const sp=b.speed*(difficulty==='easy'?.44:difficulty==='insane'?1.2:.78);const nx=b.x+dx/d*sp*dt,ny=b.y+dy/d*sp*dt;if(!cell(nx+.2*Math.sign(dx),b.y))b.x=nx;if(!cell(b.x,ny+.2*Math.sign(dy)))b.y=ny;}b.fire-=dt*(difficulty==='easy'?.5:difficulty==='insane'?1.5:1);if(b.fire<=0){b.fire=rand(difficulty==='insane'?.55:1, difficulty==='easy'?2.8:1.9);const chance=(difficulty==='easy'?.08:difficulty==='medium'?.15:difficulty==='hard'?.25:.42)*(d<4?1.3:.7);if(Math.random()<chance){player.hp-=difficulty==='insane'?18:10;damageFlash=.8;if(player.hp<=0)playerDeath(b)}}continue;}}if(b.think<=0){b.think=rand(1.2,3);b.wander=rand(0,TAU)}const nx=b.x+Math.cos(b.wander)*.25*dt,ny=b.y+Math.sin(b.wander)*.25*dt;if(!cell(nx,b.y))b.x=nx;if(!cell(b.x,ny))b.y=ny;}}
function playerDeath(b){player.hp=0;player.deaths++;scoreRed++;updateHud();addFeed(`${b.name}  ✕  VOCÊ  ·  bah, que barbaridade`);paused=true;$('#pause-title').textContent='DEITOU NA GRAMA';$('#pause-copy').textContent='Respira fundo, vivente. Bora outra?';$('#resume').textContent='VOLTAR PRA PELEIA';$('#pause').classList.add('visible');}
function pauseGame(){if(!active)return;paused=!paused;$('#pause').classList.toggle('visible',paused);if(paused){$('#pause-title').textContent='PAUSA, VIVENTE';$('#pause-copy').textContent='O mate não vai se tomar sozinho.';document.exitPointerLock?.()}else if(player.hp<=0){player.hp=100;player.x=4.5;player.y=4.5;player.ammo=30;paused=false;$('#pause').classList.remove('visible');updateHud()}}
function endGame(){active=false;paused=true;$('#pause-title').textContent='FIM DE JOGO';$('#pause-copy').textContent=scoreBlue>scoreRed?'Vitória! O churrasco é por tua conta.':'A estância ainda vai ouvir falar de ti.';$('#pause').classList.add('visible');$('#resume').textContent='JOGAR DE NOVO';}

